fn cons3(a: Int, b: Int, c: Int, rest: List[Int]) -> List[Int]
  requires len(rest) >= 0
  ensures len(result) == len(rest) + 3
  ensures result[0] == a and result[1] == b and result[2] == c
  ensures forall i in 0..len(rest): result[i + 3] == rest[i]
  effects pure
  example cons3(1, 2, 3, []) == [1, 2, 3]
  example cons3(1, 2, 3, [4]) == [1, 2, 3, 4]
{
  [a] ++ ([b] ++ ([c] ++ rest))
}

fn Interleave(s1: List[Int], s2: List[Int], s3: List[Int]) -> List[Int]
  requires (len(s1) == len(s2))
  requires (len(s2) == len(s3))
  ensures (len(result) == (3 * len(s1)))
  ensures forall i in 0..len(s1): (((result[(3 * i)] == s1[i]) and (result[((3 * i) + 1)] == s2[i])) and (result[((3 * i) + 2)] == s3[i]))
  effects pure
  example Interleave([], [], []) == []
  example Interleave([1, 2], [3, 4], [5, 6]) == [1, 3, 5, 2, 4, 6]
{
  match s1 {
    [] => []
    [h1, ..t1] => match s2 {
      [] => []
      [h2, ..t2] => match s3 {
        [] => []
        [h3, ..t3] => cons3(h1, h2, h3, Interleave(t1, t2, t3))
      }
    }
  }
}

