fn ElementWiseDivide(a: List[Int], b: List[Int]) -> List[Int]
  requires (len(a) == len(b))
  requires forall i in 0..len(b): (b[i] != 0)
  ensures (len(result) == len(a))
  ensures forall i in 0..len(result): (result[i] == (a[i] / b[i]))
  effects pure
  example ElementWiseDivide([7, -7, 9], [2, 2, 3]) == [3, -4, 3]
  example ElementWiseDivide([], []) == []
{
  match a {
    [] => []
    [h, ..t] => match b {
      [] => []
      [g, ..u] => [h / g] ++ ElementWiseDivide(t, u)
    }
  }
}

