fn no_divisor_below(n: Int, k: Int) -> Bool
  requires n >= 0 and k >= 0
  ensures result == (forall i in 2..k: ((n % i) != 0))
  effects pure
  example no_divisor_below(7, 7) == true
  example no_divisor_below(9, 9) == false
{
  if k <= 2 then true else if n % (k - 1) == 0 then false else no_divisor_below(n, k - 1)
}

fn is_prime(n: Int) -> Bool
  requires (n == n)
  ensures (result == ((n >= 2) and (forall k in 2..n: ((n % k) != 0))))
  effects pure
  example is_prime(7) == true
  example is_prime(9) == false
  example is_prime(1) == false
  example is_prime(2) == true
{
  if n < 2 then false else no_divisor_below(n, n)
}

