fn decode_cyclic(s: List[Int]) -> List[Int]
  requires (len(s) >= 0)
  ensures (len(s) == len(result))
  ensures forall i in (len(s) - (len(s) % 3))..len(s): (result[i] == s[i])
  ensures forall i in 0..(len(s) - (len(s) % 3)): ((not ((i % 3) == 0)) or (result[i] == s[(i + 2)]))
  ensures forall i in 0..(len(s) - (len(s) % 3)): ((not ((i % 3) == 1)) or (result[i] == s[(i - 1)]))
  effects pure
  example decode_cyclic([2, 3, 1, 5, 6, 4, 7]) == [1, 2, 3, 4, 5, 6, 7]
  example decode_cyclic([]) == []
  example decode_cyclic([9, 8]) == [9, 8]
{
  match s {
    [a, ..r1] => match r1 {
      [b, ..r2] => match r2 {
        [c, ..t] => [c, a, b] ++ decode_cyclic(t)
        _ => s
      }
      _ => s
    }
    _ => s
  }
}

fn NumpyBitwiseOr(x1: List[Int], x2: List[Int]) -> List[Int]
  requires (len(x1) == len(x2))
  ensures (len(result) == len(x1))
  ensures forall i in 0..len(result): (result[i] == 0)
  ensures forall i in 0..len(result): (0 == 0)
  ensures forall i in 0..len(x1): (0 == x1[i])
  ensures forall i in 0..len(x1): (0 == x1[i])
  effects pure
  example NumpyBitwiseOr([0, 0], [0, 0]) == [0, 0]
  example NumpyBitwiseOr([], []) == []
{
  match x1 {
    [] => []
    [_, ..t] => match x2 {
      [] => []
      [_, ..u] => [0] ++ NumpyBitwiseOr(t, u)
    }
  }
}

fn LogicalAnd(x1: List[Bool], x2: List[Bool]) -> List[Bool]
  requires (len(x1) == len(x2))
  ensures (len(result) == len(x1))
  ensures forall i in 0..len(result): (result[i] == (x1[i] and x2[i]))
  effects pure
  example LogicalAnd([true, false, true], [true, true, false]) == [true, false, false]
  example LogicalAnd([], []) == []
{
  match x1 {
    [] => []
    [h1, ..t1] => match x2 {
      [] => []
      [h2, ..t2] => [h1 and h2] ++ LogicalAnd(t1, t2)
    }
  }
}

