fn DoubleArrayElements(s: List[Int]) -> List[Int]
  requires (len(s) >= 0)
  ensures (len(result) == len(s))
  ensures forall i in 0..len(s): (result[i] == (2 * s[i]))
  effects pure
  example DoubleArrayElements([1, 2, 3]) == [2, 4, 6]
  example DoubleArrayElements([]) == []
{
  match s {
    [] => []
    [h, ..t] => [2 * h] ++ DoubleArrayElements(t)
  }
}

